INSERT INTO marathons(global_id, repo_gid, tracking_ref_gid, status, created_at, updated_at) VALUES('mar-01M24GDSQZHBCVK99CF6QQGJSJ', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', 'ref-01M24GDSR8FEKJD0NGYMMM2A3D', 'planned', '2026-09-10T01:55:26Z', '2026-09-10T01:55:26Z');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0BTBRMJJHRS147J73WWGGEJ', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.1.0', 'Quicksilver', 'shipped', '2026-08-01', NULL, 'Python-authoritative Tier-A twins. Licensed AGPL-3.0-only (`LICENSE`) with a commercial option (`LICENSE-COMMERCIAL.md`), adopted 2026-07-29 post-ship; the pre-existing conflicting `LICENSE.md` was removed 2026-07-30 (#372).', NULL, 'ref-01M0BTBRMJKGF9H80N3ZMF92DS', NULL, 'https://github.com/Claude-AI-Tools-Ventura-County/xyz-3-agents-swarm/issues/308', 'Quicksilver', 'No', 'No', 'Yes', NULL, NULL, NULL, '2026-09-08T05:45:05Z');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0BTBRMJW4B6HWAHKW82GFGS', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.2.0', 'Litmus', 'shipped', '2026-09-05', '2026-08-14', 'Make the checks capable of failing. Every gate in the Litmus manifest is shown to report red against a real defect, or is explicitly downgraded to advisory — a check never observed failing is not evidence (#419). Ordered first because it is the release that makes the next one measurable. It is also what the self-improvement chain (#431) is blocked on: a Reviewer is a gate, so #419 applies to it, and its qualification gate is currently un-runnable (#428) and has only ever been measured once (#429).', '`bash test/litmus-release.sh --release-gate` exits 0. Red today by design; turning it green is what "done" means. Its own negative control is `--mutate-evidence`, which must detect a stripped declaration and an unregistered gate. NOTE the honest limit, stated in that file: the audit proves registration, declaration shape and the absence of false completion claims. It does NOT prove a control was truly observed, because `gate_inventory.py` reads a declaration authored by the same person who wrote the gate. Recorded execution of each control is deliberately out of scope for this release.', 'ref-01M0BTBRMJJT3BG3V8F58X2NYZ', NULL, NULL, 'Litmus', 'No', 'No', 'Yes', NULL, NULL, NULL, '2026-08-14');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0BTBRMJNQM0474RQEYWKJKV', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.3.0', 'Nightwatch', 'shipped', '2026-10-10', '2026-08-14', 'An unattended marathon against a real target repo survives, records, and recovers. Before dispatching work, it proves the target can accept the harness write-set and preserves the local-state contract, so hostile ignore rules or linked worktrees fail clearly rather than silently splitting, leaking, or losing the run. GH-354 Phase 1 is an early Nightwatch containment prerequisite: restore clone-wide driver exclusion for linked worktrees and prove all driver pairs fail closed. A run interrupted, killed at its cap, or panicking the host leaves a durable record and recovery path instead of a clean tree full of ungated commits. Depends on Litmus. The same durability work is what makes a reflection corpus trustworthy (#431): a run with no record is invisible to any later pass over it, and the loop''s own evidence has never survived a reboot (#430).', '`bash test/nightwatch-release.sh --release-gate` exits 0. **BUILT 2026-08-11 and red by design**, exactly as Litmus''s was; turning it green is what "done" means. It has two halves because a metadata audit cannot answer this release''s question. Half A audits the frozen manifest — each entry''s gate EXISTS, is REGISTERED in `validate.sh` (a gate absent from TESTS is indistinguishable from one that passes — the #461 defect), and has a RECORDED control under `test/baselines/`; it also cross-checks that this list and the `Manifest:` line below agree, since a boundary that disagrees with itself is not frozen. Half B **executes** the lifecycle cases rather than auditing them, delegating to the suites that already drive real children and kill them rather than growing a second driver fixture here. Status on 2026-08-11: **manifest 8/8 complete; lifecycle 5 passing, 0 NOT COVERED — GOALPOST MET.** The last gap was the hostile-target write-set case, closed by #514, which was filed while executing this release and deliberately NOT admitted to the manifest (discovery is not admission); it belongs to the lifecycle list because the exit criterion always named that case — what was missing was a suite driving it. That lane also corrected its own premise: the pre-fix tree does not dispatch a turn first, it dies at the render''s `git add` with an unhandled `CalledProcessError` traceback, so the discriminating assertion is the absence of that traceback rather than the absence of a dispatch. Its own negative control is `--mutate-evidence` (34/0), which unregisters a gate and deletes a recorded control in a fixture copy, requires both to be detected, and re-checks the unmutated inputs green in the same run so an always-red detector cannot pass for one. Honest limit, inherited from Litmus: Half A reads a declaration and a filename and cannot know a recorded control was honestly recorded; Half B is what narrows that, and is why this criterion is a command that kills children rather than a checklist.', 'ref-01M0BTBRMJS3ZFBVSD21PBVSRG', NULL, NULL, 'Nightwatch', 'No', 'No', 'Yes', NULL, NULL, NULL, '2026-08-14');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0BTBRMJ4GE194HWHJJS2AV2', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.4.0', 'Plumbline', 'draft', '2026-11-14', NULL, 'Assisted reflection and a bounded self-improvement loop, measured before either is trusted. The reflection pipeline turns durable Nightwatch records into proposals (`proposals-sink.sh` gains its first production caller) and is graded against external ground truth — the 49 human-filed findings from the two rebalance-OS marathons (#405/#406) — for recall and precision. Ships a committed benchmark and a recorded go/no-go; "not worth automating yet" is a passing result, per #431''s own Phase 2 exit criterion. Operator sign-off stays manual. Depends on Nightwatch.', NULL, 'ref-01M0BTBRMKMJ8FDX4CNF6GS6HW', NULL, 'https://github.com/Claude-AI-Tools-Ventura-County/xyz-3-agents-swarm/issues/431', 'Plumbline', 'No', 'No', 'Yes', NULL, NULL, NULL, '2026-09-08T05:45:05Z');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0BTBRMKEYXGKWR47HX3S72J', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.5.0', 'Lantern', 'draft', '2026-12-12', NULL, 'When the harness fails, the information needed to act already exists inside it — make it say so. Not "add checks": every case was already detected, and some were then described wrongly (a stack trace, a fabricated path, a success exit code, silence). Scope is one epic, deliberately narrow, and deliberately NOT Nightwatch: that milestone owns run lifecycle "even when lifecycle code emits a misleading message" (see the scope boundary above), and none of Lantern''s cases violates a lifecycle invariant — they violate the legibility of a failure whose lifecycle handling was already correct. All four members were found in one afternoon during Nightwatch wave 3, which halted three times at zero paid-turn cost; each halt was avoidable from information the system already held. Depends on nothing; independent of Plumbline.', '`bash test/lantern-release.sh --release-gate` exits 0. **NOT BUILT.** Writing it precedes fixing any member, which is the Litmus and Nightwatch ordering and the reason both releases could tell a finished entry from a claimed one. Two halves, the established shape: Half A audits the frozen manifest — each entry''s gate EXISTS, is REGISTERED in `validate.sh`, has a RECORDED control under `test/baselines/`, and the list agrees with the `Manifest:` line below. Half B **executes** #499''s four phases rather than auditing them, since every one of them is a message an operator either receives or does not: a `relay-drive` launch preflight that refuses before spending, a gate refusal that states its real reason, a launcher exit code that survives its wrapper, and a change-impact report. **#358 Phase 2 is the one member with no executable half, and the criterion is written around that rather than pretending otherwise:** it is satisfied by a RECORDED transcript of a real CI failure under `test/baselines/`, and it must NOT be satisfiable by a disposition written in advance — that issue''s own capture doc forbids pre-committing one, and an exit criterion that accepted a pre-written verdict would launder exactly the thing #419 exists to prevent. Its own negative control is `--mutate-evidence`, which must unregister a gate, delete a recorded control, and substitute a pre-dated disposition for a real transcript — detecting all three, and re-checking the unmutated inputs green in the same run so an always-red detector cannot pass for one.', 'ref-01M0BTBRMK2QY9TREZSEDWFB3D', NULL, 'https://github.com/Claude-AI-Tools-Ventura-County/xyz-3-agents-swarm/issues/499', 'not created yet. The original reason — "#499 is unmilestoned by design while Nightwatch is the active goalpost" — expired when Nightwatch reached RC on 2026-08-11, and is kept here only so a reader does not act on it as if current. Creating it is a live decision, not a formality: **neither member would be enumerable by it as things stand** (#499 is unmilestoned, and #358 keeps its Nightwatch milestone deliberately), so the milestone would join nothing until #499 is assigned. The `Manifest:` line below is this release''s authoritative scope either way.', 'No', 'No', 'Yes', NULL, NULL, NULL, '2026-09-08T05:45:05Z');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.6.0', 'Front-Door', 'draft', '2026-09-26', NULL, 'XYZ can be handed to a stranger: an unauthenticated clone reaches a documented entry path and exercises a supported happy path with no private context, from a sanitized, secret-scanned tree. RE-SCOPED 2026-08-15 by explicit operator decision — originally the metering release; that work moved intact to Sundown (0.8.0). Deliverable is a sanitized fresh-history clone pushed to https://github.com/HiQS-Labs/XYZ-forge. Compacted 2026-08-20 with the RELEASES.md block; full prose in that file''s git history.', 'bash test/meter-release.sh --release-gate exits 0. NOT BUILT — written first, before any sanitization (the Litmus/Nightwatch ordering). Half A AUDITS the launch artifact: single-commit sanitized clone at the declared path; CHANGELOG.md byte-identical; .tick/, relay-system/, temp/ absent; PROJECT/ = PDDA scaffold + retained Meter example only; both LICENSE files present and consistent; secret-scan result names tool version and exact commit. Half B EXECUTES the stranger''s path: a credential-less clone of the published commit completes one supported happy path with nothing author-machine-local. Negative control --mutate-evidence: plant a private path, remove CHANGELOG.md, leave a relay-system/ behind — detect all three, re-check unmutated inputs green in the same run. RED on arrival.', 'ref-01M0BTBRMKBKXK8TVCE1A4VK01', NULL, 'https://github.com/Claude-AI-Tools-Ventura-County/xyz-3-agents-swarm/issues/563', 'Front-Door', 'Yes', 'Yes', 'Yes', NULL, NULL, NULL, '2026-09-08T05:45:05Z');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0BTBRMKKDB5TCEXT75BTFJY', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.7.0', 'Ballast', 'shipped', '2026-09-12', '2026-08-18', 'Post-launch hardening: **the launched repository holds up under a stranger''s first run and an outside contributor''s first push.** Every member was found the same way — by pointing the launch machinery at its own published output: the first fresh-clone runs of the public repository produced a different failing set each time (#15), a push gate that does not travel with clones got worse the moment the repo went public (#4), and the kernel''s own event log can drop events on the concurrent path the kernel exists to coordinate (#14). Ballast exists because publication moved the failure surface from "our machines" to "everyone else''s", and nothing in the shipped tree tests that surface. Builds on Meter''s publication; depends on nothing unshipped.', '`bash test/ballast-release.sh --release-gate` exits 0. **NOT BUILT — writing it is Ballast''s first task, before any member is fixed** (the Litmus/Nightwatch/Meter ordering; a release whose exit criterion is authored after its members cannot tell a finished entry from a claimed one). Two halves, the established shape. **Half A audits the frozen manifest:** each entry''s gate EXISTS, is REGISTERED in `validate.sh` (a gate absent from TESTS is indistinguishable from one that passes — the #461 defect), has a RECORDED control under `test/baselines/`, and the list agrees with the `Manifest-Members:` line below in both directions. **Half B EXECUTES the stranger''s path rather than auditing it:** (1) a fresh unauthenticated clone from the published commit runs the documented entry path ten consecutive times in parallel with zero failing runs — a contention warning is allowed only where it names the contended suite per #15''s contract; (2) a fresh clone with no gate installed is surfaced as ungated, in-band, on the documented first-run path, naming the one-command install (#4) — and with the gate installed, a would-be-red push is refused (a push cannot be locally refused with no hook at all; that mechanical limit is stated here rather than papered over, and #4''s fix makes the ungated state loud instead of invisible); (3) a writer killed mid-`appendEvent` loses no event, and no reader ever observes a partial `.jsonl` (#14). RED on arrival by design. Its own negative control is `--mutate-evidence`: in a fixture copy it must unregister a gate, delete a recorded control, and forge a passing stranger-run record; detect all three; and re-check the unmutated inputs green in the same run so an always-red detector cannot pass for one. **SHIPPED 2026-08-18.** `XYZ_BALLAST_STRANGER_RUNS=10 test/ballast-release.sh --release-gate` executed for real against a fresh disposable clone (`~/xyz-disposable/xyz-stranger-clone`): exit 0. Half A: 4 of 4 manifest members complete (#14, #15, #4, #3 — gate/registration/control/CLOSED-issue all confirmed). Half B: 4 of 4 passing (B1: 10/10 consecutive parallel runs with zero failures; B2a: ungated clone warning in-band; B2b: forced-red push refusal; B3: atomic-append cross-process stress case clean) — **GOALPOST MET**.', 'ref-01M0BTBRMKKR87FV1G7NT6P7HT', NULL, NULL, 'Ballast', 'No', 'No', 'Yes', NULL, NULL, NULL, '2026-08-18');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0BTBRMKFFDNYP04S68XWAPF', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.8.0', 'Sundown', 'draft', '2026-10-17', NULL, 'Retire the twelve frozen Bash twins. Three steps, in order: (1) sweep for real `XYZ_PYTHON=0` usage — if nothing sets it, the fallback is already dead in practice; (2) re-vendor every fleet `.xyz/` copy onto the Python lane (`xyz-sync.sh list` is the worklist); (3) delete the twins and retire the GH-308 edit-guard, keeping only its no-new-Bash half (GH-551). Not before steps 1-2: the vendored fleet still runs the Bash path, and `XYZ_PYTHON=0` is the documented rollback. Depends on nothing in Meter.', '**NOT WRITTEN.** Required before this release starts, per the ordering Litmus and Nightwatch both used and Meter is repeating — the gate is built first and arrives RED, because a release whose exit criterion is authored after its members cannot tell a finished entry from a claimed one.', 'ref-01M0BTBRMKX96AHAJ56H6J14MD', NULL, NULL, 'Sundown', 'No', 'No', 'Yes', NULL, NULL, NULL, '2026-09-08T05:45:05Z');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0DEBCZP752VYW4A3N2Q3YS9', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.7.1', 'Bulwark', 'shipped', '2026-08-20', '2026-08-19', 'Patch release on Ballast: the RELEASES ledger survives a git merge. A SQLite DB cannot be merged by git, so releases.sql is the canonical GID-keyed dump and the only artifact that crosses a merge boundary. Three gaps closed — clone artifacts are no longer mutated by a read-only check (#52), the .gitattributes contract and a one-command resolver pin how a conflicted dump is settled (#53), and check --rebuild now REFUSES a merge-mangled dump by name instead of throwing a traceback (#54). RELEASES-PREVIEW.md was removed: a Mac DB viewer and GitHub Projects cover the whole-ledger read.', 'test/gh32-releases-artifacts.sh, test/gh53-releases-merge-resolve.sh, test/gh54-merged-dump-refusals.sh and releases_app.py check all exit 0, AND this release''s own merge into development resolves releases.sql without a hand-edit.', 'ref-01M0DEBCZR0XW31V7WX2Q97ZBM', NULL, NULL, 'Bulwark', 'No', 'No', 'Yes', NULL, NULL, NULL, '2026-08-19');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0EC3AGK2DWYAC1WV7FMG2Q6', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.7.2', 'Daybreak', 'shipped', '2026-08-26', '2026-08-23', 'The /standup skill completes: collect.sh implements the eight bounded lens reads that feed triage.py, and the skill runs end-to-end. Dogfood release for the marathon rail itself — eight near-identical work units editing one shared collect.sh and one shared suite, which is the path-claim and collision surface the swarm exists to manage. Its PRD escalated at a 4-round review cap with a flat finding rate (11/13/10/10); the answer was to stop reviewing prose and build the deterministic half, which shipped as PR #78 with a 29-assertion suite. Daybreak finishes the job.', 'collect.sh --fixture emits all eight lenses; triage.py consumes each without a D5; test/gh77-standup-triage.sh green with per-lens assertions AND a per-lens degradation assertion; the skill runs end-to-end on this repo and its output fits the 15-line cap; validate.sh full gate green.', 'ref-01M0EC2ZXN2SS1XD2N3E56GT18', 'mar-01M0EC2ZXJCCJ88KASQPDBTBJ9', NULL, 'Daybreak', NULL, NULL, NULL, '9', '2026-08-21T04:21:29Z', 'backfilled', '2026-08-23');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0GKP4YGTHVTXHVV5WAP08B5', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.9.0', 'Cargo', 'active', '2026-09-19', NULL, 'The harness travels with its ledger: the RELEASES DB system (releases_app.py CLI + merge resolver + FAQs) and the GH-103 HTML timeline generator (utils/timeline/) ship inside every vendored .xyz/ payload as an optional, never-wired-by-default add-on — a ''when you''re ready'' module a target repo enables by running releases init itself, matching RELEASES.md''s own OPTIONAL philosophy (GH-381). Sequenced before Meter by operator decision 2026-08-20.', 'A repo vendored with xyz-vendor.sh can, with zero extra downloads, run releases init/add and export_timeline.py --preview from .xyz/ against its own root, and xyz-sync.sh update preserves the target''s ledger state (GH-312 preserve list). Nothing runs until the user invokes it.', 'ref-01M0GKP4YK2HZHWG6VZ95WGZ1G', NULL, NULL, 'Cargo', NULL, NULL, NULL, '9', '2026-09-02T03:06:54Z', 'observed', '2026-09-02T03:06:54Z');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0PJK2P8VNVJPH47BJDJG77D', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.7.3', 'Bulkhead', 'shipped', '2026-09-05', '2026-08-25', 'An unattended marathon survives its own harness. Seven radar-derived recurring defects: the suite-containment class in both polarities (destroying the caller''s clone; killing legitimate work), headless-turn reliability (scratch lane, TTY provisioning, round-cap), and the wave-reconcile writer''s drift scope.', 'Each member suite (gh8, gh2, gh50, gh113, gh114, gh115, gh168) green and registered in validate.sh; full local gate green; manifest 7/7 shipped or explicitly cut.', 'ref-01M0PJK2PCN7XP266QRPJH4HGD', NULL, NULL, 'Bulkhead', NULL, NULL, 'Yes', NULL, NULL, NULL, '2026-08-25');
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source, updated_at) VALUES('rel-01M0V6GTR1A4GX40D9CADEQA59', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0.7.4', 'Linux-RC', 'cut', '2026-09-05', NULL, 'Linux MVP release candidate: portability blockers cleared, hosted Ubuntu CI attestation on branch Linux-MVP-RC', 'All #224 checklist items closed or waived; qualifying 100% green hosted Ubuntu CI run on Linux-MVP-RC', 'ref-01M0V6GTR6D53TC85FSN41ZJNY', NULL, NULL, 'Linux MVP RC', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-08T05:45:05Z');
