INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M0Y99TQSS4PQP7WN631QDZJ5', 'rel-01M0V6GTR1A4GX40D9CADEQA59', 'ref-01M0Y99TQYXAJEYVGSAQK7QS3A', 'cut', '2026-08-26T05:39:47Z', '0.7.4''s exit criterion is a qualifying 100% green hosted Ubuntu CI run. The canary is red on development for EUID=0 reasons; a waiver cannot make the run green, so this is in-scope for Linux-RC, not deferrable to a later release.', NULL, '2026-08-26T05:39:47Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M0Y99V177CGSGP8AS3DKQPVN', 'rel-01M0V6GTR1A4GX40D9CADEQA59', 'ref-01M0Y99V1C0YRJWFV22EVZXSJV', 'cut', '2026-08-26T05:39:47Z', 'Same exit criterion: validate.sh renders an absent pytest as FAILED, so a ''green run'' claim cannot be read honestly while it stands. Cheap and adjacent to #249.', NULL, '2026-08-26T05:39:47Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M0ZA3D2KTNX3ZVVBKBAKQBZG', 'rel-01M0V6GTR1A4GX40D9CADEQA59', 'ref-01M0ZA3D2RPE4C7TJGQGP46S2B', 'cut', '2026-08-26T15:12:59Z', 'The refusal that fires when a repo cannot track harness output names every remedy except XYZ_ARCHIVE_ROOT, the one built for exactly that repo. A one-line message defect that cost three failed launch attempts on a real consuming repo.', NULL, '2026-08-26T15:12:59Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M0ZA3DB4HDQT02JK5A5YRSM1', 'rel-01M0V6GTR1A4GX40D9CADEQA59', 'ref-01M0ZA3DB8050MKG79DB8PGN7Z', 'cut', '2026-08-26T15:13:00Z', 'No preflight asks whether the builder can reach the artifact paths a phase names. When it cannot, four builder turns write nothing, the reviewer reviews an unchanged file, and the phase burns its round cap before escalating. Silent by construction and invisible to --dry-run.', NULL, '2026-08-26T15:13:00Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M11Y771SYCW50GJB92BWBSK9', 'rel-01M0V6GTR1A4GX40D9CADEQA59', 'ref-01M11Y7724XDS86C559ENBMBFB', 'cut', '2026-08-27T15:43:05Z', 'Operator-scheduled for next week''s build: two-model-verified plan, ~2-3h, retires the unlogged-teardown observability gap', NULL, '2026-08-27T15:43:05Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1AX99S7GYKRHMTQY0WTTJE6', 'rel-01M0V6GTR1A4GX40D9CADEQA59', 'ref-01M1AX99SC8FT8ZPAYFSGMGH0D', 'cut', '2026-08-31T03:19:54Z', 'The RC exit criterion requires a qualifying green Ubuntu run. It is unreachable while ~9 assertions cannot hold as root; this is the lane where they actually execute, so the #249 SKIP is a fallback rather than the permanent state.', NULL, '2026-08-31T03:19:54Z');
