INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1M3DRHVDWRY91T6WADR2NSA', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1M3DRJ1TACJC1X2V4AJG8TV', 'dialed_in', '2026-09-03T17:00:22Z', 'Front-Door Half A audits the launch artifact. This IS that audit, failed: a marker-only directory with no git history is accepted and cleared. E1-proven at HEAD.', NULL, '2026-09-03T17:00:22Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1M3DRXQ8Z6NY0YSKN89FDFW', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1M3DRXWZVPXBA53JBJVCG6D', 'dialed_in', '2026-09-03T17:00:22Z', 'Every item is a document a stranger reads and finds untrue of the tree: the no-dependencies claim, three dead README paths, a CODEX_FLAGS escalation rung that is a no-op.', NULL, '2026-09-03T17:00:22Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1M3DS9NJWF9XJYJV3AZZRBS', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1M3DS9TKSCVKQQNPH7TCMPY', 'dialed_in', '2026-09-03T17:00:23Z', 'The shipped tree''s kernel comments cite ADRs the build drops. A stranger following them dead-ends, and no gate notices. Runs against the built artifact, which is Front-Door''s subject.', NULL, '2026-09-03T17:00:23Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1M3DSNDND41DT45ZMC7D054', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1M3DSNJNF3N7KEK6GD7SYRY', 'dialed_in', '2026-09-03T17:00:23Z', 'The separated-grading guarantee AGENTS.md §12 advertises to a new reader is not enforced on the driven path. A documented guarantee that is not true is a front-door defect.', NULL, '2026-09-03T17:00:23Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1M3DT0Z0038CX8SXGY3628W', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1M3DT14MSYYASB9B8748B9Y', 'shipped', '2026-09-03T17:00:23Z', 'A stranger following the README''s operator path seeds .tick/ in the wrong directory; the driven path is protected only because it pins the root.', NULL, '2026-09-03T17:00:23Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1M3DTCT03B6JW3H3F8NQDPK', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1M3DTCZ05VSHP2G1RRD9HXZ', 'dialed_in', '2026-09-03T17:00:24Z', 'AGENTS.md §4 tells a new reader the guard blocks driver calls. It blocks six of twelve. Same class: a stated guarantee narrower than its mechanism.', NULL, '2026-09-03T17:00:24Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1M3DTRGD1J90Z6FCAQKW5EF', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1M3DTRPMD53CY81B8M6TVNM', 'dialed_in', '2026-09-03T17:00:24Z', 'Flaky turns under concurrency are the first thing a new operator hits and the hardest to attribute; the transient case is indistinguishable from a real loss.', NULL, '2026-09-03T17:00:24Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1M9HXP0TM9MJED9039542KF', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1M9HXP6MAVCEM5RDPX29BSP', 'dialed_in', '2026-09-03T18:47:30Z', 'A stranger following the documented intake rail parks an item the planner cannot see. Front-Door is about the path a new reader actually walks.', NULL, '2026-09-03T18:47:30Z');
INSERT INTO manifest_items(global_id, release_gid, issue_ref_gid, state, dialed_in_at, dial_reason, marathon_gid, updated_at) VALUES('mfi-01M1MAQ794AFT5K00B844DE6KP', 'rel-01M0BTBRMKX17AQN7Q11A0YCD7', 'ref-01M1MAQ799D901VHERKBBJZVFA', 'dialed_in', '2026-09-03T19:07:52Z', 'Front-Door is about the path a stranger walks. A marathon process nobody can follow reliably is that path failing one layer up.', NULL, '2026-09-03T19:07:52Z');
