INSERT INTO grandfather_entries(import_run, release_gid, rule, source_value, supplied_value, disposition, updated_at) VALUES('imp-20260819T013222-50951f', 'rel-01M0BTBRMJNQM0474RQEYWKJKV', 'description-length', 'An unattended marathon against a real target repo survives, records, and recover...', NULL, NULL, '2026-09-08T05:45:05Z');
INSERT INTO grandfather_entries(import_run, release_gid, rule, source_value, supplied_value, disposition, updated_at) VALUES('imp-20260819T013222-50951f', 'rel-01M0BTBRMJNQM0474RQEYWKJKV', 'exit-criterion-length', '2007 chars', NULL, NULL, '2026-09-08T05:45:05Z');
INSERT INTO grandfather_entries(import_run, release_gid, rule, source_value, supplied_value, disposition, updated_at) VALUES('imp-20260819T013222-50951f', 'rel-01M0BTBRMJNQM0474RQEYWKJKV', 'shipped-prose-extracted', 'Shipped: 2026-08-14 — RC 2026-08-11 on `development`, soak window 3 days, re-verified at ship on `86ba3bd5`: `bash test/nightwatch-release.sh --release-gate` → exit 0, **manifest 8/8 complete, lifecycle 5 passing / 0 failing / 0 NOT COVERED**. Half B *executes* the lifecycle cases rather than auditing them, so this is a run that killed real children and watched them recover — not a checklist. Falsification check on the soak window found nothing: the exit command was re-run on a `development` that already contains every fix landed 08-11 → 08-14, including GH-314 (the marathon transcript write-set), which is adjacent to this release''s subject and was the one worth checking. The hostile-target write-set lifecycle case still passes via `gh514-write-set-trackable.sh`. Open non-manifest issues (#514, #467, #402, #392, #391, #386) do **not** hold this release open — the exit criterion never named them, and a milestone is a backlog, not a goalpost.', '2026-08-14', NULL, '2026-09-08T05:45:05Z');
INSERT INTO grandfather_entries(import_run, release_gid, rule, source_value, supplied_value, disposition, updated_at) VALUES('imp-20260819T013222-50951f', 'rel-01M0BTBRMJNQM0474RQEYWKJKV', 'tracking-issue-missing', NULL, 'MIG-D248B2', NULL, '2026-09-08T05:45:05Z');
INSERT INTO grandfather_entries(import_run, release_gid, rule, source_value, supplied_value, disposition, updated_at) VALUES('imp-20260819T013222-50951f', 'rel-01M0BTBRMJW4B6HWAHKW82GFGS', 'shipped-prose-extracted', 'Shipped: 2026-08-14 — RC 2026-08-09 on `development` @ `263816c`, soak window 5 days, re-verified at ship on `86ba3bd5`: `bash test/litmus-release.sh --release-gate` → exit 0, 6/6 complete, 0 false completion claims. **The ship test was the release''s own exit command, not an issue-state audit.** Convention settled 2026-08-14: an exit criterion that is MET *is* the definition of done; a release is not held open by issues it never named. Falsification check on the soak window found nothing — every issue filed 08-09 → 08-14 (#485, #491, #499, #503, #504, #509, #510, #514, #518, #520, #521, #522, #523, #525, #527, #528, #533, #534, #536, #539, #540, #542, #544) either shipped inside it or left the exit command green, and the command was re-run on a `development` containing all of those fixes.', '2026-08-14', NULL, '2026-09-08T05:45:05Z');
