INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23V8F0R5ET8B6T536Z81', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '23', 'GH-23 · Kernel invariant: enforce path-overlap rejection on direct tick claim and tick scope', 'Completed', '45', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-23-KERNEL-OVERLAP-ENFORCEMENT.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/23', '- **GH-23 · Kernel invariant: enforce path-overlap rejection on direct tick claim and tick scope** ✅ **SHIPPED — issue closed 2026-08-19; built on `fix/gh-23-kernel-overlap-enforcement`** — enforce collision-free path claims at the kernel boundary by rejecting direct `tick claim` and `tick scope` when requested paths overlap active claims held by other agents; wire `--force` bypass; add regression test coverage. → [GH-23-KERNEL-OVERLAP-ENFORCEMENT.md](PROJECT/3-COMPLETED/GH-23-KERNEL-OVERLAP-ENFORCEMENT.md) · [#23](https://github.com/HiQS-Labs/XYZ-forge/issues/23) (rated 82/78/72/60)', '2026-08-19T18:55:40Z', '2026-08-26T05:32:04Z', '82', '78', '72', '60', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23V80KAQSQP9C3V07BS0', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '57', 'GH-57 · test(releases): SQLite ledger fuzzing recipes & multi-scenario resilience suite', 'Completed', '42', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-57-RELEASES-SQLITE-FUZZING.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/57', '- **GH-57 · test(releases): SQLite ledger fuzzing recipes & multi-scenario resilience suite** ✅ **SHIPPED 2026-08-19 (PR #60 + PR #70; issue closed)** — synthetic fuzzing recipes and edge-case scenario coverage in `test/gh57-releases-fuzz.sh` (42/42 assertions) for concurrent branch divergence, multi-generation merge headers, duplicate settings/GID collisions, crash injection & journal recovery at 5 boundaries, common-dir lock contention, torn dump protection, and Markdown drift; evaluated non-interactive model routing across Muse Spark, Qwen 3.8-Max, GLM-5.2, and Codex. → [GH-57-RELEASES-SQLITE-FUZZING.md](PROJECT/3-COMPLETED/GH-57-RELEASES-SQLITE-FUZZING.md) · [#57](https://github.com/HiQS-Labs/XYZ-forge/issues/57) (rated 60/45/65/50)', '2026-08-19T18:55:40Z', '2026-09-08T03:59:21Z', '60', '45', '65', '50', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23V9XAQT9ZC2C2P7Y6MT', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '45', 'GH-45 · validate.sh must refuse to run from a linked worktree — an observed run corrupted the parent clone', 'Completed', '43', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-45-WORKTREE-GATE-REFUSAL.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/45', '- **GH-45 · validate.sh must refuse to run from a linked worktree — an observed run corrupted the parent clone** ✅ **SHIPPED 2026-08-18 (PR #55, built on `development` in clone `XYZ-forge-gh35`; issue closed 2026-08-19)** — `validate.sh` AND `ci-local.sh` now refuse (exit 2, before anything runs, every tier) when invoked from a linked git worktree, using the issue''s verified `--absolute-git-dir` vs `--git-common-dir` comparison anchored on both HERE and the CWD. The refusal names the observed 2026-08-19 damage (core.bare=true, origin repointed, remote refs deleted, development overwritten with fixture commits); `XYZ_ALLOW_WORKTREE_GATE=1` overrides and announces itself. Pinned in `test/gh35-test-tiers.sh` §9 incl. the required control (normal checkout of the same repo still runs, silently). → [GH-45-WORKTREE-GATE-REFUSAL.md](PROJECT/3-COMPLETED/GH-45-WORKTREE-GATE-REFUSAL.md) · [#45](https://github.com/HiQS-Labs/XYZ-forge/issues/45) · [#564](https://github.com/Claude-AI-Tools-Ventura-County/xyz-3-agents-swarm/issues/564) (rated 65/60/60/70)', '2026-08-19T18:55:40Z', '2026-08-26T05:32:04Z', '65', '60', '60', '70', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23V92G58WA014AZYZGPR', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '35', 'GH-35 · 3-tier test suite selection (docs / utility subsystems / core) + CPU governance', 'Completed', '22', '✅', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-35-TEST-TIER-ROUTING.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/35', '- **GH-35 · 3-tier test suite selection (docs / utility subsystems / core) + CPU governance** ✅ **Phases 1+2 BUILT 2026-08-18 on `development` (standalone clone `XYZ-forge-gh35`)** — one fail-closed subsystem registry in `utils/ci-route.sh` (hq, releases, telemetry, ate, swe-diagram, pdda, agent2agent) consumed by `githooks/pre-push` and `validate.sh`; `--tier/--subsystem/--auto/--paths-file`; the parallel default rebalanced from `cores-2` (up to 8) to `cores/2` (cap 4) with every worker under `nice -n 10`, plus `--throttle`/`--burst`/`XYZ_VALIDATE_THROTTLE`/`XYZ_VALIDATE_MAX_JOBS`. Utility pushes drop from the full ~4-min pool to their focused suites (~20-45s target, measurement owed). New suite `test/gh35-test-tiers.sh` 56/0; pre-push suite extended to 85/0. Phase 3 (CI alignment + every-file-classified sweep) pending. rated 55/45/50/45. → [GH-35-TEST-TIER-ROUTING.md](PROJECT/2-WORKING/GH-35-TEST-TIER-ROUTING.md) · [#35](https://github.com/HiQS-Labs/XYZ-forge/issues/35)', '2026-08-19T18:55:40Z', '2026-08-25T02:10:14Z', '55', '45', '50', '45', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23V90JN51W09HEABFVYX', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '39', 'GH-39 · RELEASES app: one-way GitHub Project release-card projection', 'Completed', '44', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-39-RELEASES-PROJECT-SYNC.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/39', '- **GH-39 · RELEASES app: one-way GitHub Project release-card projection** ✅ **SHIPPED 2026-08-18 (issue closed)** — explicit `project sync` dry-run/apply writer maps every ledger release by immutable Release ID, refuses mismatched Project schema, and keeps GitHub cards read-only from the ledger’s perspective. → [GH-39-RELEASES-PROJECT-SYNC.md](PROJECT/3-COMPLETED/GH-39-RELEASES-PROJECT-SYNC.md) · [#39](https://github.com/HiQS-Labs/XYZ-forge/issues/39) (rated 50/30/65/45)', '2026-08-19T18:55:40Z', '2026-08-26T05:32:04Z', '50', '30', '65', '45', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VANQ7D8Y804WVDTEC7', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '42', 'GH-42 · relay automation: supported Commandcode turn-taker', 'Completed', '23', '✅', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-42-COMMANDCODE-TURN.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/42', '- **GH-42 · relay automation: supported Commandcode turn-taker** ✅ **CLOSED 2026-08-22 (issue closed; ledger reconciled)** — add a Python-authoritative, containment-preserving Commandcode adapter with mocked regression coverage; Muse Spark Contributor is the initial builder and Codex performs independent QA. rated 50/35/55/45. → [GH-42-COMMANDCODE-TURN.md](PROJECT/2-WORKING/GH-42-COMMANDCODE-TURN.md) · [#42](https://github.com/HiQS-Labs/XYZ-forge/issues/42)', '2026-08-19T18:55:40Z', '2026-08-25T02:10:14Z', '50', '35', '55', '45', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VAR6KPD0ZX6Q8WKWZR', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '32', 'GH-32 · RELEASES app: SQLite-backed release ledger, CLI-only writes, generated RELEASES.md, cross-repo UI', 'Queue / parked intake', '10', '🚧', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-32-RELEASES-APP-SQLITE.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/32', '- **GH-32 · RELEASES app: SQLite-backed release ledger, CLI-only writes, generated RELEASES.md, cross-repo UI** 🚧 **Phase 0+1 BUILT and merged 2026-08-19 (PR #34, builder GLM 5.3 per the #33 evaluation)** — schema/CLI/writer-protocol/canonical-dump/import landed (`utils/py/releases_app.py`, suite 81/0, full gate green, independently verified); the PRD survived a 4-round Codex sol-high relay review first. Still ahead: the `/releases` route migration (Phase 0 entry gate for the measured dogfood window), the Phase 2 strict flip, and the Phase 3 cockpit card. rated 70/50/65/35. → [GH-32-RELEASES-APP-SQLITE.md](PROJECT/1-INBOX/GH-32-RELEASES-APP-SQLITE.md) · [#32](https://github.com/HiQS-Labs/XYZ-forge/issues/32) · [#33](https://github.com/HiQS-Labs/XYZ-forge/issues/33)', '2026-08-19T18:55:40Z', '2026-08-25T00:18:27Z', '70', '50', '65', '35', NULL);
