INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VB7XZ4620GZAX07X6R', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '10', 'GH-10 · prevent-half of containment: require_fixture adoption across the fixture-creating suites + adoption guard + ci-local identity bracket', 'Completed', '21', '✅', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-10-REQUIRE-FIXTURE-ADOPTION.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/10', '- **GH-10 · prevent-half of containment: require_fixture adoption across the fixture-creating suites + adoption guard + ci-local identity bracket** ✅ **CLOSED 2026-08-22 (issue closed; ledger reconciled)** — resolves the 2026-08-17 marathon cut (enforcement without adoption) by adopting for real: `_setup.sh` centrally, 35 suites mechanically, 7 by hand (out-of-root fixtures nested under pinned sandboxes); `test/gh1-adoption-guard.sh` derives offenders from source every run (exemptions declared in-file — no permanent exception list), controls prove it fires; `ci-local.sh` gains the GH-1 identity bracket; ledger records **Unaudited suites: 0**. Drive-by: fixture-guard.sh shellcheck `-S error` fix (pre-existing ci-local red). rated 55/70/50/80. → [GH-10-REQUIRE-FIXTURE-ADOPTION.md](PROJECT/2-WORKING/GH-10-REQUIRE-FIXTURE-ADOPTION.md) · [#10](https://github.com/HiQS-Labs/XYZ-forge/issues/10)', '2026-08-19T18:55:40Z', '2026-08-25T02:10:14Z', '55', '70', '50', '80', NULL);
