INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VBW9KQM2ZAA9Q76YPQ', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '5', 'GH-5 · kernel robustness: node:test unit runner', 'In progress', '9', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-5-EVENTS-QUARANTINE-UNIT-TESTS.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/5', '- **GH-5 · kernel robustness: node:test unit runner** 🆕 **active 2026-08-15 on `gh-5/events-quarantine-unit-tests` (public-repo tracker)** — 11 direct unit tests on the built-in `node:test` runner (was 13; the 2 quarantine-dependent tests deferred to #14), zero new dependencies, `npm run test:unit`, `npm test` → `validate.sh` unchanged. The quarantine-in-reader approach was rejected on orchestrator review per the correction on #5 (silent event loss on the concurrent path while writes are non-atomic) and re-routed to #14. **#5 stays open until this PR''s tests and #14''s atomic write have both landed.** rated 45/40/45/80. → [GH-5-EVENTS-QUARANTINE-UNIT-TESTS.md](PROJECT/2-WORKING/GH-5-EVENTS-QUARANTINE-UNIT-TESTS.md) · [#5](https://github.com/HiQS-Labs/XYZ-forge/issues/5)', '2026-08-19T18:55:40Z', '2026-08-25T19:33:01Z', '45', '40', '45', '80', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VCTAKM1VSFSAGBDEMG', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '4', 'GH-4 · the pre-push gate does not travel with clones: fresh clones push unverified', 'Completed', '46', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-4-GATE-TRAVELS-WITH-CLONES.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/4', '- **GH-4 · the pre-push gate does not travel with clones: fresh clones push unverified** ✅ **SHIPPED 2026-08-17, orchestrator-authored directly** — `validate.sh` warns non-fatally when the clone is ungated (verified both directions: fires when ungated, silent when gated); README documents the install step as a correctness requirement. A prior driven-marathon attempt escalated after 5 rounds without landing this (see `test/baselines/GH-4-negative-control.md`''s design note). → [GH-4-GATE-TRAVELS-WITH-CLONES.md](PROJECT/3-COMPLETED/GH-4-GATE-TRAVELS-WITH-CLONES.md) · [#4](https://github.com/HiQS-Labs/XYZ-forge/issues/4) (rated 78/72/70/60)', '2026-08-19T18:55:40Z', '2026-08-26T05:32:03Z', '78', '72', '70', '60', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VCM10Y0A1WGWRPMMFP', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '14', 'GH-14 · appendEvent writes non-atomically, so concurrent readers can observe torn event files', 'Completed', '47', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-14-ATOMIC-EVENT-APPEND.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/14', '- **GH-14 · appendEvent writes non-atomically, so concurrent readers can observe torn event files** ✅ **SHIPPED 2026-08-17 (PR #21)** — `appendEvent` writes to a `.tmp` name then `renameSync`s into place; a `.jsonl` file that exists is always complete. `test/gh14-atomic-append.sh` 6/0; negative control `test/baselines/GH-14-negative-control.md` (5/1 pre-fix). Gap: the two `test/unit/events.test.js` cases deferred from PR #7 (quarantine, empty-file skip) were not re-authored; #5 stays open on that gap. → [GH-14-ATOMIC-EVENT-APPEND.md](PROJECT/3-COMPLETED/GH-14-ATOMIC-EVENT-APPEND.md) · [#14](https://github.com/HiQS-Labs/XYZ-forge/issues/14) (rated 85/85/70/55)', '2026-08-19T18:55:40Z', '2026-08-26T05:32:03Z', '85', '85', '70', '55', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VCQXCBHY8XSCPV4CEB', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '15', 'GH-15 · parallel runs are unreliable in a fresh clone; the GH-528 contention retry is not honoring its contract', 'Completed', '48', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-15-PARALLEL-FRESH-CLONE-RELIABILITY.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/15', '- **GH-15 · parallel runs are unreliable in a fresh clone; the GH-528 contention retry is not honoring its contract** ✅ **SHIPPED 2026-08-17 (PR #20 + orchestrator reconciliation)** — `validate.sh`''s parallel retry gives every suite `stdin=/dev/null`, adds a completeness catch-up for suites with no result line, and a tally-integrity guard. `test/gh528-parallel-contention-retry.sh` 9/0; negative control `test/baselines/GH-15-parallel-contention-negative-control.md` (5/4 pre-fix). Ten consecutive parallel fresh-clone runs: 10/10 exit 0, zero failures, zero contention. → [GH-15-PARALLEL-FRESH-CLONE-RELIABILITY.md](PROJECT/3-COMPLETED/GH-15-PARALLEL-FRESH-CLONE-RELIABILITY.md) · [#15](https://github.com/HiQS-Labs/XYZ-forge/issues/15) (rated 80/75/70/50)', '2026-08-19T18:55:40Z', '2026-08-26T05:32:03Z', '80', '75', '70', '50', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VDGC5DDKFA3CXYXTZB', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '3', 'GH-3 · improve-loop.sh --state-dir durability — provenance evidence must not evaporate', 'Completed', '49', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-3-IMPROVE-LOOP-STATE-DIR.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/3', '- **GH-3 · improve-loop.sh --state-dir durability — provenance evidence must not evaporate** ✅ **SHIPPED 2026-08-17 (closed as landed)** — durable default and path-printing were already landed pre-Ballast (GH-430); the sole remaining gap, a recorded negative control, closed 2026-08-17 (`test/baselines/GH-3-state-dir-negative-control.md`, 6/2 pre-fix → 8/0 post-fix). → [GH-3-IMPROVE-LOOP-STATE-DIR.md](PROJECT/3-COMPLETED/GH-3-IMPROVE-LOOP-STATE-DIR.md) · [#3](https://github.com/HiQS-Labs/XYZ-forge/issues/3) (rated 55/45/55/65)', '2026-08-19T18:55:40Z', '2026-08-26T05:32:02Z', '55', '45', '55', '65', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DQ00PCDP50DH1TFMSE4AV4', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '67', 'GH-67 · Commandcode builder default widened to `--yolo` — closer evaluation → possible build', 'Queue / parked intake', '9', '🆕', NULL, NULL, NULL, NULL, 'https://github.com/HiQS-Labs/XYZ-forge/issues/67', '- **GH-67 · Commandcode builder default widened to `--yolo` — closer evaluation → possible build** 🆕 **queued 2026-08-19 as the NEXT immediate item (operator call, session close)** — PR #60 moved the default from the bounded `--permission-mode auto-accept` to `--yolo` (alias for `--dangerously-skip-permissions`), unmentioned in a fuzzing PR. Evaluate whether the turn shim’s containment (worktree isolation, `ALLOW_PATHS`, commit-bypass guard) genuinely makes the child CLI’s permission mode irrelevant; if yes, RATIFY — write the containment argument down in AGENTS.md/the shim docs and pin it — if no, revert the default and drop the `--yolo` test pin. Sibling check either way: `claude-turn.py` uses `--permission-mode acceptEdits`; confirm the two adapters differ on purpose. rated 88/80/45/70 ovr 340. → [#67](https://github.com/HiQS-Labs/XYZ-forge/issues/67)', '2026-08-19T19:12:00Z', '2026-08-25T00:18:27Z', '88', '80', '45', '70', '340');
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DZZGNQVK65X0Y63AYGCM4E', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '75', 'GH-75 · single-page HTML dashboard: releases (mid/long term) + roadmap (immediate) in one read-only view', 'Queue / parked intake', '7', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-75-RELEASES-ROADMAP-DASHBOARD.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/75', '- **GH-75 · single-page HTML dashboard: releases (mid/long term) + roadmap (immediate) in one read-only view** 🆕 **queued 2026-08-19 at the FRONT of the line (operator call)** — a `releases dashboard` verb renders one self-contained HTML file from `releases.db`, with a card per release (version, codename, status, target, days-to-target, manifest open/closed split, exit criterion) and a card per `roadmap_items` row grouped by section in ledger order, plus a header strip carrying generation, receipt count, and a stale-sync banner when `ROADMAP.md` is ahead of the shadow. Read-only by construction: no writer lock, no generation bump, no receipt — safe to run mid-merge. First real consumer of the GH-69 shadow rows. rated 90/40/85/55. → [#75](https://github.com/HiQS-Labs/XYZ-forge/issues/75)', '2026-08-19T21:49:01Z', '2026-08-27T17:56:05Z', '90', '40', '85', '55', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DZZGNRVEH9GPW7J3VPBP4B', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '61', 'GH-61 · RELEASES ledger durability hardening (GH-57 follow-up)', 'Queue / parked intake', '8', '🆕', NULL, NULL, NULL, NULL, 'https://github.com/HiQS-Labs/XYZ-forge/issues/61', '- **GH-61 · RELEASES ledger durability hardening (GH-57 follow-up)** 🆕 **queued 2026-08-19 — filed 2026-08-19 out of the PR #60 review and un-triaged until now** — four scoped test follow-ups under one parent: exact ledger state asserted after crash recovery ([#62](https://github.com/HiQS-Labs/XYZ-forge/issues/62)), writer-lock stress and owner-death recovery ([#63](https://github.com/HiQS-Labs/XYZ-forge/issues/63)), seeded malformed-dump property coverage ([#64](https://github.com/HiQS-Labs/XYZ-forge/issues/64)), and a portable artifact-hash helper ([#65](https://github.com/HiQS-Labs/XYZ-forge/issues/65)). rated 45/55/40/50. → [#61](https://github.com/HiQS-Labs/XYZ-forge/issues/61)', '2026-08-19T21:49:01Z', '2026-09-09T20:53:03Z', '45', '55', '40', '50', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0E5Z0TP7WTZFKS6SQYW17KK', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '77', 'GH-77 · `/standup` — session-scoped triage: what did I leave open, what is rotting, is the plan still right?', 'Completed', '27', '✅', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-77-STANDUP-SESSION-TRIAGE.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/77', '- **GH-77 · `/standup` — session-scoped triage: what did I leave open, what is rotting, is the plan still right?** ✅ **CLOSED 2026-08-22 (issue closed; ledger reconciled)** — the instrument the operator reaches for constantly, and the answer to the confidence problem the 2026-08-19 audit exposed: a shipped release left `active` for a day, four ledger markers contradicting GitHub, five issues filed into no index — all discoverable in seconds, none discovered by anything. Session + local state only (no history sweep; `/radar` keeps that job), park-only write authority, both halves every run, tactical list hard-capped at 7 items and the strategic read at ~5 lines. Carries an interface catalogue for the RELEASES CLI, the ROADMAP entry schema, PDDA lifecycle, and the one-marathon rail, so every recommendation names the exact command that closes it. rated 95/70/85/30. → [GH-77-STANDUP-SESSION-TRIAGE.md](PROJECT/1-INBOX/GH-77-STANDUP-SESSION-TRIAGE.md) · [#77](https://github.com/HiQS-Labs/XYZ-forge/issues/77) · [GH-77-STANDUP-SESSION-TRIAGE.md](PROJECT/2-WORKING/GH-77-STANDUP-SESSION-TRIAGE.md)', '2026-08-19T23:33:36Z', '2026-08-25T02:10:14Z', '95', '70', '85', '30', NULL);
