INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0FWQ1S70PWTTVM7P23QR298', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '91', 'GH-91 · a build turn has nowhere to write verification output', 'Completed', '5', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-91-RELAY-SCRATCH-DIR.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/91', '- **GH-91 · a build turn has nowhere to write verification output ** ✅ **SHIPPED 2026-08-24 (PR #214)** — containment kills a complete, green turn** ✅ **CLOSED 2026-08-22 (issue closed; ledger reconciled)** — issue option 1: `.relay-scratch/` as an intrinsic write category — pre-created by `rtl_worktree_begin`, exempted in `rtl_worktree_end` (no signature check; never copied back), exempted-and-discarded in `rtl_check` (non-worktree path), and NAMED in `rtl_turn_prompt` at the point of use. New suite `test/gh91-relay-scratch.sh` 15/0 with controls (stray still exit-6, lookalike prefix not exempt, off-lane copies nothing back); containment-pinning neighbors green. Surfaced by the daybreak wave-1 re-fire after #90. rated 60/65/55/75. → [GH-91-RELAY-SCRATCH-DIR.md](PROJECT/3-COMPLETED/GH-91-RELAY-SCRATCH-DIR.md) · [#91](https://github.com/HiQS-Labs/XYZ-forge/issues/91)', '2026-08-20T15:30:27Z', '2026-08-25T02:10:14Z', '60', '65', '55', '75', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0FY5VR7R33M0WVBBCNJSTA3', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '101', 'GH-101 · Feasibility Study: Promoting Programmatic Script Runner (`script_runner.py`) into Core Relay & Consult Runtimes', 'Completed', '38', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-101-FEASIBILITY-STUDY-SCRIPT-RUNNER.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/101', '- **GH-101 · Feasibility Study: Promoting Programmatic Script Runner (`script_runner.py`) into Core Relay & Consult Runtimes** ✅ **SHIPPED 2026-08-20 (issue closed)** — evaluated and promoted programmatic tool mode across `consult.py` and `relay_drive.py` behind `--tool-mode programmatic` (default off); completed 3-test qualification ladder (Test 1 architectural review & fail-closed threat scoping; Test 2 consult dogfooding with throwaway worktree isolation, pre-created `.relay-scratch/`, and 1,935-trial paired density benchmark in `TESTS-RESULTS/2026-08-20+GH-101/`; Test 3 relay-drive PGID process cleanup stress and fail-closed sandbox checks in `test/synthetic/gh101-relay-programmatic-stress.sh`); promoted to Production-Ready (A-Grade) in `HARNESS-MODELS-REGISTRY.md`. → [GH-101-FEASIBILITY-STUDY-SCRIPT-RUNNER.md](PROJECT/3-COMPLETED/GH-101-FEASIBILITY-STUDY-SCRIPT-RUNNER.md) · [#101](https://github.com/HiQS-Labs/XYZ-forge/issues/101) (rated 45/20/70/40)', '2026-08-20T15:56:01Z', '2026-08-26T05:32:05Z', '45', '20', '70', '40', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0G0PGX85DBNMZC2HSJ6MF7H', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '102', 'GH-102 · Unify Telemetry Schema & Inspection Tooling Across Fuzzing and ATE', 'Completed', '40', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-102-UNIFIED-TELEMETRY-TOOLING.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/102', '- **GH-102 · Unify Telemetry Schema & Inspection Tooling Across Fuzzing and ATE** ✅ **SHIPPED 2026-08-20 (issue closed)** — standardized shared data contract (`schema_version: "1.0"`), instrumented `utils/fuzzing/fuzz-loop.sh` with argv-safe JSONL emission and sub-second millisecond timing; updated `utils/ate/scripts/run_variations.py` to triage `tokens_source` (`api_usage` vs `config_provided` vs `unsupported`); upgraded `utils/ate/scripts/checkin.py` into a universal inspector with nearest-rank percentiles and comparative side-by-side mode; verified via `test/synthetic/gh102-telemetry-schema.sh` (8/8 PASS) and archived receipts in `TESTS-RESULTS/2026-08-20+GH-102/`. → [GH-102-UNIFIED-TELEMETRY-TOOLING.md](PROJECT/3-COMPLETED/GH-102-UNIFIED-TELEMETRY-TOOLING.md) · [#102](https://github.com/HiQS-Labs/XYZ-forge/issues/102) (rated 68/45/70/45)', '2026-08-20T16:40:04Z', '2026-08-26T05:32:05Z', '68', '45', '70', '45', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0GKR98JB3PHQE1BN7H77Q3X', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '105', 'GH-105 · vendor the RELEASES DB system + HTML timeline generator into the `.xyz` payload (optional add-on)', 'Completed', '6', '🆕', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-105-VENDOR-RELEASES-ADDON.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/105', '- **GH-105 · vendor the RELEASES DB system + HTML timeline generator into the `.xyz` payload (optional add-on)** 🆕 **queued 2026-08-20; sole frozen manifest entry of new release 0.9.0 "Cargo" (target 2026-09-19, before Meter, operator call); delivery contract superseded by GH-197 (two-tier, 2026-08-23)** — was: always in the vendored payload, never wired by default: `releases_app.py` + merge resolver + FAQs + `utils/timeline/`, with target-repo ledger state at the target root and GH-312 preserve-list coverage. rated 75/50/60/45. → [GH-105-VENDOR-RELEASES-ADDON.md](PROJECT/3-COMPLETED/GH-105-VENDOR-RELEASES-ADDON.md) · [#105](https://github.com/HiQS-Labs/XYZ-forge/issues/105)', '2026-08-20T22:13:04Z', '2026-08-28T14:51:10Z', '75', '50', '60', '45', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0GKR98K9X9FYJVH6CPSQ2BP', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '103', 'GH-103 · technical spike: RELEASES SQLite → timeline-ui ledger viewer (RELEASES dashboard view)', 'Completed', '39', '✅', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-103-TIMELINE-LEDGER-SPIKE.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/103', '- **GH-103 · technical spike: RELEASES SQLite → timeline-ui ledger viewer (RELEASES dashboard view)** ✅ **SHIPPED 2026-08-20 (PR #104; issue closed)** — read-only exporter `utils/timeline/export_timeline.py` projects `releases.db` into timeline-ui''s `data.json` contract; viewer `utils/timeline/RELEASES.html` (header collapse caret, full-viewport liquid layout, scrollable detour lanes); `--preview` bakes the committed `RELEASES-PREVIEW.html` snapshot, auto-refreshed after every CLI write by the GH-106 hook; `--serve` answers `/data.json` live from the DB; band-aware RELEASES.md-vs-DB drift banner. Zero DB writes (SQLite `mode=ro`). Prototype for the queued #75 `releases dashboard` verb; follow-on integration tracked in #107 (Cargo). → [GH-103-TIMELINE-LEDGER-SPIKE.md](PROJECT/1-INBOX/GH-103-TIMELINE-LEDGER-SPIKE.md) · [#103](https://github.com/HiQS-Labs/XYZ-forge/issues/103) (rated 62/35/75/50)', '2026-08-20T22:13:04Z', '2026-08-26T05:32:06Z', '62', '35', '75', '50', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0H9CC0981F9CSAMV7BXRYXP', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '111', 'GH-111 · retire manifest FREEZE; tasks and marathons are DIALED IN to exactly one release, as a database state', 'Completed', '35', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-111-DIALED-IN.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/111', '- **GH-111 · retire manifest FREEZE; tasks and marathons are DIALED IN to exactly one release, as a database state** ✅ **SHIPPED 2026-08-21 (PR #116; issue closed)** — membership became machine-checkable instead of a sentence someone remembered to write: three states (`dialed_in`/`shipped`/`cut`), exclusivity by a partial unique index over ACTIVE membership only, a real `releases migrate` upgrade path where none existed, and BASELINES replacing what the freeze used to buy (progress against the live manifest, growth against the kickoff count). Closed #109 (the viewer asserted marathon membership the data never claimed) and #110 (`shipped` was a state nothing could write). rated 85/75/70/35. → [GH-111-DIALED-IN.md](PROJECT/3-COMPLETED/GH-111-DIALED-IN.md) · [#111](https://github.com/HiQS-Labs/XYZ-forge/issues/111)', '2026-08-21T04:31:03Z', '2026-08-25T02:10:14Z', '85', '75', '70', '35', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0H9CC0AAF9JWBSHR3679NQQ', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '108', 'GH-108 · pri/sev/appeal/effort — the canonical task rating system (calc sum + operator override)', 'Completed', '36', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-108-RATING-SYSTEM.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/108', '- **GH-108 · pri/sev/appeal/effort — the canonical task rating system (calc sum + operator override)** ✅ **SHIPPED 2026-08-21 (PR #116; issue closed)** — one scoring vocabulary for every task in the ledger, oriented so a single glance answers what should go to the front of the line: four axes 1-100 where higher is always better (effort scores cheapness), a combined 4-400 `calc` derived and never stored, and an `ovr` override that pins anything visible. Authored as `rated N/N/N/N` on a ROADMAP entry; read via `bash utils/leaderboard.sh` or LEADERBOARD.html. rated 80/50/75/40. → [GH-108-RATING-SYSTEM.md](PROJECT/3-COMPLETED/GH-108-RATING-SYSTEM.md) · [#108](https://github.com/HiQS-Labs/XYZ-forge/issues/108)', '2026-08-21T04:31:03Z', '2026-08-25T02:10:14Z', '80', '50', '75', '40', NULL);
