INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0KXV2WWSQVF6AQ0H4NQ7REY', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '135', 'GH-135..140 · Wave-1 follow-ups: consult preflight verdict, attempts-gate root, suite registration, twin-divergence record, SIGPIPE sweep+guard, utcnow swap', 'Completed', '33', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-135-CONSULT-AGY-PREFLIGHT.md', NULL, '- **GH-135..140 · Wave-1 follow-ups: consult preflight verdict, attempts-gate root, suite registration, twin-divergence record, SIGPIPE sweep+guard, utcnow swap** ✅ **SHIPPED 2026-08-22 (PR #145, squash 9c07f0cc; issues closed)** — six follow-up issues fixed on one branch: consult.py routes non-zero whoami exits through the shared verdict (#135); TICK_REPO_ROOT resolves ahead of the lane-attempt gate with the NOTE still after the lock (#136); the Wave-1 suites + the gh139 guard registered in TESTS (#137); the post-#129 twin divergence pinned (#138); 369 of 482 pipe-into-`grep -q` sites swept to capture-then-match with a ratchet guard over a ~120-entry shrinking baseline (#139 — the sweep''s own gate run caught and repaired three negation-inversion conversions and signal-triage''s escaped-quote mangle, each verified by suite re-run); the three utcnow() sites swapped timezone-aware (#140). Full gate 237/237; relay QA by agy returned VERDICT: PASS. → [GH-135-CONSULT-AGY-PREFLIGHT.md](PROJECT/3-COMPLETED/GH-135-CONSULT-AGY-PREFLIGHT.md) · [GH-136-ATTEMPTS-GATE-ROOT.md](PROJECT/3-COMPLETED/GH-136-ATTEMPTS-GATE-ROOT.md) · [GH-137-SUITE-REGISTRATION.md](PROJECT/3-COMPLETED/GH-137-SUITE-REGISTRATION.md) · [GH-138-TWIN-DIVERGENCE-RECORD.md](PROJECT/3-COMPLETED/GH-138-TWIN-DIVERGENCE-RECORD.md) · [GH-139-SIGPIPE-SWEEP-GUARD.md](PROJECT/3-COMPLETED/GH-139-SIGPIPE-SWEEP-GUARD.md) · [GH-140-UTCNOW-DEPRECATION.md](PROJECT/3-COMPLETED/GH-140-UTCNOW-DEPRECATION.md) (rated 58/45/60/55)', '2026-08-22T05:07:05Z', '2026-08-26T05:32:06Z', '58', '45', '60', '55', NULL);
