INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0T6MXXT5RJZ7SA9523MYSBT', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '202', 'GH-202 · wave_reconcile aborts on marathon-plan exit 5 (items held) and promotes capture docs for OPEN issues', 'Completed', '9', '✅', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-202-WAVE-RECONCILER-STATE.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/202', '- **GH-202 · wave_reconcile aborts on marathon-plan exit 5 (items held) and promotes capture docs for OPEN issues** ✅ **SHIPPED 2026-08-24 (PR #210)** — hotfix, the reconciler sits on every merge critical path** — tolerate the items-held planning state (log + continue), and consult the linked issue''s open/closed state before promoting a doc: OPEN keeps the doc active with recorded merge evidence (idempotent), unknown state promotes as before (offline-manifest backward compat). rated 85/65/85/70. → [GH-202-WAVE-RECONCILER-STATE.md](PROJECT/2-WORKING/GH-202-WAVE-RECONCILER-STATE.md) · [#202](https://github.com/HiQS-Labs/XYZ-forge/issues/202)', '2026-08-24T15:36:27Z', '2026-08-25T02:10:14Z', '85', '65', '85', '70', NULL);
