INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M0BT84BCG7MZTZXPSJKNYV', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '406', 'External review (Russ K.): eight findings on guards that cover a narrower path than the doc claims', 'Queue / parked intake', '34', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-406-RUSS-EXTERNAL-REVIEW.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/406', '- **GH-406 · External review (Russ K.): eight findings on guards that cover a narrower path than the doc claims** 🆕 **captured 2026-09-03 via HQ** — all eight reproduce at HEAD; five are one class (a doc states a guarantee, the mechanism covers a narrower path, nothing compares the two — the §13 anti-pattern). R1 wire --relay-file into rtl_enforce · R2 guard tick log for task.* · R3 typed transient claim exit 75 · R4 drop the destructive-rebuild marker · R5 PDDA comment-reference check · R6 glob the guard hook. rated 3/3/4/3 [ovr 4] — [GH-406-RUSS-EXTERNAL-REVIEW.md](PROJECT/1-INBOX/GH-406-RUSS-EXTERNAL-REVIEW.md) · [#406](https://github.com/HiQS-Labs/XYZ-forge/issues/406)', '2026-09-03T16:06:52Z', '2026-09-03T16:06:52Z', '3', '3', '4', '3', '4');
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M3B6RQB0PQJK017M2RCHE2', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '410', 'relay-block validator never runs on the driven path', 'Completed', '35', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-410-RELAY-BLOCK-VALIDATOR-DRIVEN-PATH.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/410', '- **GH-410 · The structural relay-block validator never runs on the driven path, and rejects the bold STATUS format real threads write** 🆕 **captured 2026-09-03 via HQ** — §12''s separated-grading guarantee is enforced only when the model volunteers --relay-file. Plus two follow-on defects: the rtl_enforce backstop no-ops on the healthy path (GH-67), and the validator''s literal ^STATUS: match rejects the bold form real threads write (GH-92). Zero test coverage today. /3/3/3 [ovr 4] — [GH-410-RELAY-BLOCK-VALIDATOR-DRIVEN-PATH.md](PROJECT/2-WORKING/GH-410-RELAY-BLOCK-VALIDATOR-DRIVEN-PATH.md) · [#410](https://github.com/HiQS-Labs/XYZ-forge/issues/410) (rated 95/80/90/40)', '2026-09-03T16:58:58Z', '2026-09-08T03:59:28Z', '95', '80', '90', '40', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M3B78KQ2A649QHFWXF9VJE', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '412', 'transient claim collision indistinguishable from durable loss', 'Completed', '36', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-412-TRANSIENT-CLAIM-EXIT-CODE.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/412', '- **GH-412 · A transient O_EXCL claim collision exits 1, identical to a durable loss — no retry channel under marathon load** 🆕 **captured 2026-09-03 via HQ** — lock.js throws a bare Error on EEXIST, tick maps every throw to 1, rtl.py fails the turn with no retry. Follow-up to shipped GH-408, which unified the three DURABLE lost exits and never considered EEXIST. Distinct exit 75 plus a --json result line. /3/3/2 [ovr 4] — [GH-412-TRANSIENT-CLAIM-EXIT-CODE.md](PROJECT/1-INBOX/GH-412-TRANSIENT-CLAIM-EXIT-CODE.md) · [#412](https://github.com/HiQS-Labs/XYZ-forge/issues/412) (rated 80/75/75/55)', '2026-09-03T16:58:59Z', '2026-09-08T03:59:28Z', '80', '75', '75', '55', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M3B7MK4Y0S1T8B9Z6PANAJ', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '413', 'launch-artifact marker authorises destructive rebuild', 'Completed', '37', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-413-LAUNCH-ARTIFACT-MARKER-DESTRUCTION.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/413', '- **GH-413 · The launch-artifact marker authorises a destructive rebuild of any directory — marker alone, no git history required** 🆕 **captured 2026-09-03 via HQ** — E1 at HEAD: a dir holding nothing but a copied marker and two files passes the destination guard; the control without the marker is refused. Both halves (marker plus build script) are tracked, so any public reader holds the mechanism. Delete the marker; guard multi-commit destinations. /4/1/1 [ovr 4] — [GH-413-LAUNCH-ARTIFACT-MARKER-DESTRUCTION.md](PROJECT/1-INBOX/GH-413-LAUNCH-ARTIFACT-MARKER-DESTRUCTION.md) · [#413](https://github.com/HiQS-Labs/XYZ-forge/issues/413) (rated 90/95/85/95)', '2026-09-03T16:58:59Z', '2026-09-08T03:59:28Z', '90', '95', '85', '95', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M3CA27TY8RHZ7KQMXXCC5Y', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '411', 'tick log exempt from the foreign-cwd guard', 'Completed', '38', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-411-TICK-LOG-FOREIGN-CWD-GUARD.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/411', '- **GH-411 · tick log is exempt from the foreign-cwd guard — the verb that seeds every run, plus the whole marathon namespace** 🆕 **captured 2026-09-03 via HQ** — assertResolvedRoot returns early on the verb not the event type, so task.created and every marathon type seed a .tick log in whatever cwd resolved. Guard everything except cost. — [GH-411-TICK-LOG-FOREIGN-CWD-GUARD.md](PROJECT/1-INBOX/GH-411-TICK-LOG-FOREIGN-CWD-GUARD.md) · [#411](https://github.com/HiQS-Labs/XYZ-forge/issues/411) (rated 75/70/70/80)', '2026-09-03T16:59:34Z', '2026-09-08T03:59:28Z', '75', '70', '70', '80', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M3CAEDR1GFMEPRDEQ1T924', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '414', 'nothing checks whether an inline code comment is still true', 'Completed', '39', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-414-COMMENT-REFERENCE-CHECK.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/414', '- **GH-414 · Nothing deterministic checks whether an inline code comment is still true — extend the dead-reference resolver past the doc boundary** ✅ **SHIPPED 2026-09-04 (PR #427)** — extend the dead-reference resolver past the doc boundary** 🆕 **captured 2026-09-03 via HQ** — pdda-check-governance already resolves dead references in markdown; it stops at the document boundary, so kernel comments citing absent ADRs stay green forever. Extend the glob to source comments, run against both trees, and triage the existing warning stream. — [GH-414-COMMENT-REFERENCE-CHECK.md](PROJECT/3-COMPLETED/GH-414-COMMENT-REFERENCE-CHECK.md) · [#414](https://github.com/HiQS-Labs/XYZ-forge/issues/414) (rated 60/45/85/70)', '2026-09-03T16:59:35Z', '2026-09-04T15:39:50Z', '60', '45', '85', '70', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M3CATFWYEBT1934NQW6J9E', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '415', 'guard hook covers 6 of 12 Tier-A entrypoints', 'Completed', '40', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-415-GUARD-HOOK-DERIVE-ENTRYPOINTS.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/415', '- **GH-415 · The skill-first guard hook covers 6 of 12 Tier-A entrypoints — derive the set from AGENTS.md instead of hardcoding it** ✅ **SHIPPED 2026-09-04 (PR #438)** — derive the set from AGENTS.md instead of hardcoding it** 🆕 **captured 2026-09-03 via HQ** — six literal filenames against a surface of twelve; the authoritative enumeration already exists at AGENTS.md 230-232. Direct instance of Radar T3''s open derive-from-source item. Also fixes a false positive where any command merely mentioning a driver path is blocked. — [GH-415-GUARD-HOOK-DERIVE-ENTRYPOINTS.md](PROJECT/3-COMPLETED/GH-415-GUARD-HOOK-DERIVE-ENTRYPOINTS.md) · [#415](https://github.com/HiQS-Labs/XYZ-forge/issues/415) (rated 65/55/70/80)', '2026-09-03T16:59:35Z', '2026-09-04T17:04:16Z', '65', '55', '70', '80', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M3CB6E0MKZNSCR4BM0EESS', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '416', 'four documentation trues-ups', 'Queue / parked intake', '41', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-416-DOC-TRUES-UP-BATCH.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/416', '- **GH-416 · Four documentation trues-ups — package.json vs §7, dead PROJECT 4-MISC refs, CODEX_FLAGS default and dead escalation rung, uncommitted ROUTER pointer** 🆕 **captured 2026-09-03 via HQ** — each is a document stating something not literally true of the tree. CODEX_FLAGS has two halves: the default omits the approval flag AND the documented escalation rung is a no-op because that flag is already the default. — [GH-416-DOC-TRUES-UP-BATCH.md](PROJECT/1-INBOX/GH-416-DOC-TRUES-UP-BATCH.md) · [#416](https://github.com/HiQS-Labs/XYZ-forge/issues/416) (rated 50/30/60/95)', '2026-09-03T16:59:36Z', '2026-09-03T16:59:56Z', '50', '30', '60', '95', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1M9HWTHDERQGFZMFX3EQS60', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '418', 'Marathon planner still reads the frozen ROADMAP.md', 'Queue / parked intake', '42', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-418-MARATHON-ADOPT-RELEASES-DB.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/418', '- **GH-418 · Marathon planner still reads the frozen ROADMAP.md — DB-parked items are invisible since the ROADMAP_SOURCE=releases flip** 🆕 **captured 2026-09-03 via HQ** — .pdda-mode says the DB is planning truth and router_audit calls ROADMAP.md frozen legacy, but marathon_plan.py:126 reads ROADMAP.md and neither planner file mentions the flip (0 grep hits). Proof: the 09-01/09-02 plans surface #349/#351, which exist only in ROADMAP.md and not in roadmap_items. 37 DB-parked items are unplannable. Concrete testable slice of GH-269. — [GH-418-MARATHON-ADOPT-RELEASES-DB.md](PROJECT/2-WORKING/GH-418-MARATHON-ADOPT-RELEASES-DB.md) · [#418](https://github.com/HiQS-Labs/XYZ-forge/issues/418) (rated 88/78/80/75) — depends on GH-423 (the rendered ledger artifact this planner consumes)', '2026-09-03T18:47:29Z', '2026-09-10T01:55:23Z', '88', '78', '80', '75', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1MAQ6G07ACPBGQY822RG1T9', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '419', 'make the three marathon process rules deterministic', 'Completed', '43', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-419-MARATHON-RULE-ENFORCEMENT.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/419', '- **GH-419 · Make the three marathon process rules deterministic — umbrella issue, full clone, derived clone name — by extending marathon.sh''s existing --plan refusal** 🆕 **captured 2026-09-03 via HQ** — three conditions added to the GH-212 refusal block that already exists; one new MARATHON.yaml key. Consulted: Codex and agy both REVISE. Adopted unanimously — primary-checkout half of rule 2 dropped. Codex blocker confirmed — bin/marathon-yaml rejects unknown top-level keys, so the parser change is in scope. Tie broken on umbrella key vs name-derivation: kept the key as sole identity source. — [GH-419-MARATHON-RULE-ENFORCEMENT.md](PROJECT/1-INBOX/GH-419-MARATHON-RULE-ENFORCEMENT.md) · [#419](https://github.com/HiQS-Labs/XYZ-forge/issues/419) (rated 72/60/75/78)', '2026-09-03T19:07:51Z', '2026-09-08T03:59:29Z', '72', '60', '75', '78', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1N0AXTVP8VJ9EPW8CJK1VNY', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '421', 'Wave reconciliation is never invoked automatically — wire it post-merge, but fix its ledger write first', 'Queue / parked intake', '44', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-421-AUTO-WAVE-RECONCILE.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/421', '- **GH-421 · Wave reconciliation is never invoked automatically — wire it post-merge, but fix its ledger write first** 🆕 **captured 2026-09-04 via HQ** — wave_reconcile.py (GH-165) already moves docs, syncs the ledger, regenerates dashboards and replans the next wave, and its CLI is shaped for unattended use; nothing fires it. Measured: #420 and #409 both merged 2026-09-03 and neither reconciled. BLOCKER on ordering — its only ledger call is `releases roadmap sync`, a deliberate no-op in releases-mode, while it still writes shipping into the frozen ROADMAP.md, so automating it first would write a wrong record at machine speed and exit 0. Phase 1 gives it manifest ship / roadmap repoint; Phase 2 wires pull_request:closed; Phase 3 lands the artifacts. — [GH-421-AUTO-WAVE-RECONCILE.md](PROJECT/2-WORKING/GH-421-AUTO-WAVE-RECONCILE.md) · [#421](https://github.com/HiQS-Labs/XYZ-forge/issues/421) (rated 85/75/88/50)', '2026-09-04T01:25:38Z', '2026-09-10T01:55:23Z', '85', '75', '88', '50', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1N0C5V50EF6E84T906RQE8W', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '423', 'releases roadmap render: emit the DB as ledger markdown — the missing verb #418 actually depends on', 'Queue / parked intake', '45', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-423-ROADMAP-RENDER.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/423', '- **GH-423 · releases roadmap render: emit the DB as ledger markdown — the missing verb GH-418 actually depends on** 🆕 **captured 2026-09-04 via HQ** — QUEUE_PLAN_ROADMAP takes a FILE path and nothing renders roadmap_items in the shape the planner parses, so GH-418 has been summarized with an option ("accept the shim") that is empty. The two ledger-bullet parsers already mirror each other by hand, and roadmap_items stores raw_text verbatim, so the verb is a replay not a generator. Leaves the 64KB engine byte-unchanged and serves the nine other skills still reading ROADMAP.md. — [GH-423-ROADMAP-RENDER.md](PROJECT/2-WORKING/GH-423-ROADMAP-RENDER.md) · [#423](https://github.com/HiQS-Labs/XYZ-forge/issues/423) (rated 80/60/85/88)', '2026-09-04T01:26:19Z', '2026-09-10T01:55:24Z', '80', '60', '85', '88', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1N1Z8Z2150Z58DQJM5PW6PK', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '424', 'roadmap_items.status_marker has no CLI writer — in releases-mode a row can never leave 🆕', 'Queue / parked intake', '46', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-424-ROADMAP-STATUS-MARKER-WRITER.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/424', '- **GH-424 · roadmap_items.status_marker has no CLI writer — in releases-mode a row can never leave 🆕** 🆕 **captured 2026-09-04 via HQ** — roadmap update has --raw-text and --section but no marker arg; repoint writes only doc_path/raw_text; the only thing that ever set it was roadmap sync parsing the legacy markdown, a no-op here. 50 rows sit at 🆕 including shipped work. Ships an enum-validated --status-marker, NOT derivation from raw_text (that re-couples schema to markdown — agy over Codex). Also closes the rollback gap: the journal never snapshots RELEASES.generated.md, so a rewound DB leaves it ahead and releases check fails generation-mismatch after a rollback reported as successful. Hard prerequisite for GH-421. — [GH-424-ROADMAP-STATUS-MARKER-WRITER.md](PROJECT/2-WORKING/GH-424-ROADMAP-STATUS-MARKER-WRITER.md) · [#424](https://github.com/HiQS-Labs/XYZ-forge/issues/424) (rated 90/70/75/70)', '2026-09-04T01:54:13Z', '2026-09-10T01:55:24Z', '90', '70', '75', '70', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1N1ZJP33J5G3NW3JK6A2YS3', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '425', '--gate''s provenance check never compares the PR number — it proves TESTS-RESULTS/ is non-empty', 'Queue / parked intake', '47', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-425-GATE-PROVENANCE-CHECK.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/425', '- **GH-425 · --gate provenance check never compares the PR number — it proves TESTS-RESULTS/ is non-empty and reports receipts verified** 🆕 **captured 2026-09-04 via HQ** — check_provenance_receipts reads pr_num, walks the tree, trips on the first provenance.jsonl anywhere, never compares it, then prints "Provenance receipts verified for PR #{pr_num}". Receipts are committed here, so the gate cannot fail; no test coverage, no red control. The GH-406 defect class inside the flag meant to be the safety catch. Gates closeout, not merging — exposure is a false provenance record. Prerequisite for GH-421 Phase 2. — [GH-425-GATE-PROVENANCE-CHECK.md](PROJECT/2-WORKING/GH-425-GATE-PROVENANCE-CHECK.md) · [#425](https://github.com/HiQS-Labs/XYZ-forge/issues/425) (rated 78/65/80/85)', '2026-09-04T01:54:23Z', '2026-09-10T01:55:25Z', '78', '65', '80', '85', NULL);
