INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M1T8H5J5P8TZ9Y5M194E91JN', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '454', 'wave_reconcile dies on an unnamed release, and enforces PDDA full-mode on an observe-mode repo', 'Queue / parked intake', '54', '🆕', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-454-RECONCILE-GATE-DEFECTS.md', 'https://github.com/HiQS-Labs/XYZ-forge/issues/454', '- **GH-454 · wave_reconcile dies on an unnamed release, and enforces PDDA full-mode on an observe-mode repo** 🆕 **captured 2026-09-05 via /file-xyz-bug from `rebalanceOS`** — two defects, one run, each rolling the whole wave back: `export_timeline.py:278` does `(codename or version).lower()` and raises on a release row with both NULL; `run_validation_gate()` fails on any stdout line containing `ERROR`, ignoring `pdda.sh`''s mode-aware exit code and so enforcing `full` on a repo that declares `observe`. Both have workarounds the caller must already know. With GH-215''s surviving half, this is what blocks GH-421 unattended operation. rated 72/78/80/78 — [GH-454-RECONCILE-GATE-DEFECTS.md](PROJECT/2-WORKING/GH-454-RECONCILE-GATE-DEFECTS.md)', '2026-09-06T02:25:03Z', '2026-09-10T01:55:25Z', '72', '78', '80', '78', NULL);
